-- OTOTR FRANCHISE CONTRACT DISCARD RPC CANDIDATE
create or replace function finance_private.current_franchise_contract_discard_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_franchise_contract_discard_scope(p_actor_id uuid,p_contract_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_api.authorize_franchise_contract_discard(p_contract_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when auth.uid() is null or p_permission<>'finance.contracts.discard' then null::jsonb else finance_private.resolve_franchise_contract_discard_scope(auth.uid(),p_contract_id,p_permission) end$$;
create or replace function finance_api.commit_franchise_contract_discard(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_contract_id uuid,p_reversal_date date,p_reason_code text,p_expected_version bigint,p_note_hash text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare c finance.franchise_contracts%rowtype;v_existing record;v_new bigint;v_payload jsonb;v_previous text;v_audit text;
begin
 if not finance_private.current_franchise_contract_discard_committer_is_trusted() then raise exception using errcode='42501',message='trusted franchise contract discard committer required';end if;
 if p_expected_version<1 or p_reversal_date is null or pg_catalog.length(pg_catalog.btrim(coalesce(p_reason_code,''))) not between 1 and 100 or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') or pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='invalid franchise contract discard command';end if;
 select * into c from finance.franchise_contracts where id=p_contract_id for update;if not found then raise exception using errcode='P0002',message='contract not found';end if;
 select om.payload into v_existing from finance.outbox_messages om where om.legal_entity_id=c.legal_entity_id and om.event_type='FRANCHISE_CONTRACT_DRAFT_DISCARDED' and om.aggregate_id=c.id and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if v_existing.payload->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','contractId',c.id,'status','DISCARDED','version',(v_existing.payload->>'version')::bigint);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if c.legal_entity_id<>p_legal_entity_id or c.dealer_legal_entity_id<>p_dealer_legal_entity_id or c.status<>'DRAFT' or c.version<>p_expected_version then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if exists(select 1 from finance.contract_versions cv where cv.franchise_contract_id=c.id and cv.status in ('PENDING_APPROVAL','APPROVED','ACTIVE','SUPERSEDED')) then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=p_dealer_account_id and da.legal_entity_id=p_legal_entity_id and da.dealer_legal_entity_id=p_dealer_legal_entity_id and b.id=p_branch_id) then raise exception using errcode='42501',message='contract discard three dimensional scope denied';end if;
 v_new:=c.version+1;update finance.franchise_contracts set status='DISCARDED',version=v_new,correlation_id=p_correlation_id where id=c.id;
 v_payload:=pg_catalog.jsonb_build_object('contractId',c.id,'dealerLegalEntityId',c.dealer_legal_entity_id,'branchId',p_branch_id,'reversalDate',p_reversal_date,'reasonCode',p_reason_code,'noteHash',p_note_hash,'version',v_new,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.contract','FRANCHISE_CONTRACT_DRAFT_DISCARDED','FRANCHISE_CONTRACT',c.id,v_new,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=p_legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||c.id::text||':FRANCHISE_CONTRACT_DRAFT_DISCARDED:'||p_intent_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,reason_code,before_hash,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','FRANCHISE_CONTRACT_DRAFT_DISCARDED','FRANCHISE_CONTRACT',c.id,'ALLOW',p_reason_code,p_intent_hash,p_intent_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('branchId',p_branch_id,'reversalDate',p_reversal_date,'noteHash',p_note_hash,'previousVersion',c.version),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','DISCARDED','contractId',c.id,'status','DISCARDED','version',v_new);
end$$;
revoke all on function finance_private.current_franchise_contract_discard_committer_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_franchise_contract_discard_scope(uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_api.authorize_franchise_contract_discard(uuid,text) from public,anon;grant execute on function finance_api.authorize_franchise_contract_discard(uuid,text) to authenticated;revoke all on function finance_api.commit_franchise_contract_discard(uuid,uuid,uuid,uuid,uuid,uuid,date,text,bigint,text,text,text,uuid) from public,anon,authenticated;
